'use client';

import { closeBrackets, closeBracketsKeymap } from '@codemirror/autocomplete';
import {
  copyLineDown,
  copyLineUp,
  cursorMatchingBracket,
  indentLess,
  indentMore,
  moveLineDown,
  moveLineUp,
  standardKeymap,
  toggleComment,
} from '@codemirror/commands';
import {
  bracketMatching,
  HighlightStyle,
  indentUnit,
  LanguageDescription,
  syntaxHighlighting,
} from '@codemirror/language';
import { languages } from '@codemirror/language-data';
import { search, searchKeymap } from '@codemirror/search';
// oxlint-disable-next-line react-doctor/prefer-dynamic-import -- This opt-in component is the loading boundary; extensions must exist when its adapter mounts.
import { EditorState } from '@codemirror/state';
// oxlint-disable-next-line react-doctor/prefer-dynamic-import -- This opt-in component is the loading boundary; extensions must exist when its adapter mounts.
import { EditorView, keymap, runScopeHandlers } from '@codemirror/view';
import { tags } from '@lezer/highlight';
import { AuthoredPlugin } from 'platejs/authored';
import { createCodeMirrorAdapter } from 'platejs/code-block/codemirror';
import { useEditorSelector } from 'platejs/react';

import {
  CodeBlockContainer,
  type CodeBlockElementProps,
} from '@/registry/components/editor/code-block-container';
import {
  findCodeBlockLanguage,
  resolveCodeBlockLanguage,
} from '@/registry/components/editor/code-block-languages';

const syntaxColors = syntaxHighlighting(
  HighlightStyle.define([
    { tag: tags.keyword, class: 'hljs-keyword' },
    { tag: [tags.string, tags.regexp], class: 'hljs-string' },
    { tag: [tags.number, tags.bool, tags.null], class: 'hljs-number' },
    { tag: tags.comment, class: 'hljs-comment' },
    { tag: tags.function(tags.variableName), class: 'hljs-title function_' },
    { tag: [tags.typeName, tags.className], class: 'hljs-type' },
    { tag: tags.propertyName, class: 'hljs-attr' },
  ])
);

// Fences store catalog values such as `objectivec`, `docker`, or `wasm`, which
// CodeMirror only knows by value, label, or alias.
const languageDescription = (name?: string) => {
  if (!name) return null;

  const option = findCodeBlockLanguage(name);

  for (const candidate of [
    name,
    ...(option ? [option.value, option.label, ...(option.aliases ?? [])] : []),
  ]) {
    const description = LanguageDescription.matchLanguageName(
      languages,
      candidate,
      false
    );

    if (description) return description;
  }

  return null;
};

const codeMirrorLanguages = [
  { label: 'Plain Text', value: 'plaintext' },
  ...languages.map(({ alias, name }) => ({
    aliases: alias,
    label: name,
    value: name.toLowerCase(),
  })),
];

/**
 * Normalize a typed fence language for CodeMirror, keeping languages that
 * CodeMirror parses separately (`tsx`, `jsx`, `sass`, `webassembly`) while
 * still mapping shared aliases (`ts` to `typescript`, `py` to `python`) and
 * keeping single-word fence slugs (such as `lisp`, `ini`, `properties`).
 */
export function resolveCodeMirrorLanguage(raw: string) {
  const normalized = raw.trim().toLowerCase();

  if (!normalized) return undefined;

  const matched = findCodeBlockLanguage(normalized, codeMirrorLanguages)?.value;

  if (matched && (!matched.includes(' ') || normalized.includes(' '))) {
    return matched;
  }

  return resolveCodeBlockLanguage(normalized);
}

const codeMirrorAdapter = createCodeMirrorAdapter({
  extensions: [
    syntaxColors,
    indentUnit.of('  '),
    EditorState.tabSize.of(2),
    search({ top: true }),
    closeBrackets(),
    bracketMatching(),
    keymap.of(searchKeymap),
    keymap.of(
      [
        { key: 'Tab', run: indentMore, shift: indentLess },
        { key: 'Alt-ArrowUp', run: moveLineUp },
        { key: 'Alt-ArrowDown', run: moveLineDown },
        { key: 'Shift-Alt-ArrowUp', run: copyLineUp },
        { key: 'Shift-Alt-ArrowDown', run: copyLineDown },
        { key: 'Mod-/', run: toggleComment },
        { key: 'Shift-Mod-\\', run: cursorMatchingBracket },
        ...closeBracketsKeymap,
        ...standardKeymap,
      ].map((binding) => ({ ...binding, scope: 'code-block' }))
    ),
    EditorView.domEventHandlers({
      keydown(event, view) {
        // Composition starts before CodeMirror observes its first text mutation.
        if (event.isComposing || view.compositionStarted) return false;
        return runScopeHandlers(view, event, 'code-block');
      },
    }),
    EditorView.theme({
      '&': {
        backgroundColor: 'transparent',
        color: 'inherit',
      },
      '&.cm-focused': { outline: 'none' },
      '.cm-content': {
        caretColor: 'currentColor',
        fontFamily: 'ui-monospace, SFMono-Regular, Menlo, monospace',
        fontSize: '0.875rem',
        lineHeight: 'normal',
        padding: '2rem 1rem 2rem 2rem',
      },
      '.cm-scroller': {
        maxHeight: 'min(70vh, 48rem)',
        overflow: 'auto',
      },
      '[data-code-block-model-selection]': {
        backgroundColor:
          'color-mix(in srgb, var(--editor-primary, var(--primary)) 25%, transparent)',
      },
      '.cm-search': {
        alignItems: 'center',
        backgroundColor: 'var(--background)',
        borderBottom: '1px solid var(--border)',
        display: 'flex',
        flexWrap: 'wrap',
        gap: '0.25rem',
        padding: '0.375rem',
      },
      '.cm-search input': {
        backgroundColor: 'var(--background)',
        border: '1px solid var(--input)',
        borderRadius: '0.375rem',
        color: 'inherit',
        padding: '0.25rem 0.5rem',
      },
      '.cm-search button': {
        border: '1px solid var(--border)',
        borderRadius: '0.375rem',
        padding: '0.25rem 0.5rem',
      },
      '@media print': {
        '.cm-scroller': {
          maxHeight: 'none',
          overflow: 'visible',
        },
      },
    }),
  ],
  loadLanguage(name) {
    const description = languageDescription(name);

    return description?.support ?? description?.load() ?? [];
  },
});

export function CodeBlockCodeMirrorElement({
  addon,
  showLanguageLabel = true,
  ...props
}: CodeBlockElementProps) {
  const authoredNative = useEditorSelector(
    (current) => {
      const authored = current.plugin(AuthoredPlugin);

      if (!authored.installed) return false;

      const view = authored.read.view();

      if ('intent' in view && view.intent === 'propose') return true;
      if ('preview' in view) return false;

      const path = current.read.nodes.path(props.element);

      return Boolean(
        path && authored.read.changes({ at: path, limit: 1 }).items.length > 0
      );
    },
    { dependsOn: 'authored' }
  );
  const useNative = props.element.children.length !== 1 || authoredNative;

  return (
    <CodeBlockContainer
      addon={addon}
      elementProps={props}
      languageOptions={codeMirrorLanguages}
      showLanguageLabel={showLanguageLabel}
    >
      {useNative ? (
        <pre className="overflow-x-auto p-8 pe-4 font-mono text-sm leading-[normal] [tab-size:2] print:break-inside-avoid">
          <code>{props.children}</code>
        </pre>
      ) : (
        props.slots.externalText({
          adapter: codeMirrorAdapter,
          ariaLabel: 'Code block',
          config: { language: props.element.language },
        })
      )}
    </CodeBlockContainer>
  );
}
